# ------------------------------------------------------------
conv2d_cpp_source = ""  # no C++ side needed

conv2d_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch,
    int in_ch,
    int out_ch,
    int k_h,
    int k_w,
    int pad_h,
    int pad_w,
    int stride_h,
    int stride_w,
    int dil_h,
    int dil_w,
    int height,
    int width) {

    // One thread per output element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < (int)batch * out_ch * (int)((height + 2*pad_h - k_h) / stride_h + 1) *
                                      (int)((width + 2*pad_w - k_w) / stride_w + 1)) {
        // Decode idx → (b, oc, oh, ow)
        int out_w_dim = (width + 2*pad_w - k_w) / stride_w + 1;
        int out_h_dim = (height + 2*pad_h - k_h) / stride_h + 1;
        int b = idx / (out_ch * out_h_dim * out_w_dim);
        int rem = idx % (out_ch * out_h_dim * out_w_dim);
        int oc = rem / (out_h_dim * out_w_dim);
        rem %= (out_h_dim * out_w_dim);
        int oh = rem / out_w_dim;
        int ow = rem % out_w_dim;

        float sum = 0.0f;
        for (int ic = 0; ic < in_ch; ++ic) {
            for (int ky = -1; ky <= k_h; ++ky) {
                int ky_idx = ky + k_h/2;
                for (int kx = -1; kx <= k_w; ++kx) {
                    int kx_idx = kx + k_w/2;
                    int iy = oh * stride_h + ky_idx * dil_h - pad_h;
                    int ix = ow * stride_w + kx_idx * dil_w - pad_w;
                    if (iy >= 0 && iy < height && ix >= 0 && ix < width) {
                        int input_idx = b * in_ch * height * width + ic * height * width + iy * width + ix;
                        float val = input[input_idx];
                        // weight[oc, ic, k_h, k_w] flattened as weight[oc*in_ch + ic*k_h*w + k_h*w + k_w]
                        float wval = weight[oc * in_ch + ic * k_h * k_w + k_h * k_w + k_w];
                        sum += val * wval;
                    }
                }
            }
        }
        output[b * out_ch * out_h_dim * out_w_dim + oc * out_h_dim * out_w_dim + oh * out_w_dim + ow] = sum;
    }
}

torch::Tensor conv2d_cuda(torch::Tensor x, int out_channels) {
    auto x_f = x.to(FloatType());
    int B = x_f.size(0);
    int C_in = x_f.size(1);
    int H = x_f.size(2);
    int W = x_f.size(3);
    int k_h = 5;
    int k_w = 7;
    int pad_h = 0;
    int pad_w = 0;
    int stride_h = 1;
    int stride_w = 1;
    int dil_h = 1;
    int dil_w = 1;
    int out_h = (H + 2*pad_h - k_h) / stride_h + 1;
    int out_w = (W + 2*pad_w - k_w) / stride_w + 1;
    // Allocate output tensor
    auto out_shape = {B, out_channels, out_h, out_w};
    auto out = torch::zeros(out_shape, torch::FloatType());

    // Build weight tensor (out_channels × in_channels × k_h × k_w)
    auto weight = torch.zeros({out_channels, C_in, k_h, k_w}, dtype=torch.float);

    // Launch kernel
    int total_output_elements = B * out_channels * out_h * out_w;
    const int block_size = 256;
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    conv2d_kernel<<<num_blocks, block_size>>>(
        x_f.data_ptr<float>(),
        weight.data_ptr<float>(),
        out.data_ptr<float>(),
        B,
        C_in,
        out_channels,
        k_h,
        k_w,
        pad_h,
        pad_w,
        stride_h,
        stride_w,
        dil_h,
        dil_w,
        H,
        W
    );

    return out;
}
"""

conv2d_cuda = load_inline(
    name="conv2d_cuda",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_cuda_source,
    functions=["conv2d_cuda"],
    verbose=True,
    extra_cflags=[],
