# 3️⃣  Optimized model (replaces the original nn.Conv2d with the custom CUDA op)
# ------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.in_channels = 64
        self.out_channels = 128
        self.kernel_size = (5, 7)
        self.stride = (1, 1)
        self.padding = (0, 0)
        self.dilation = (1, 1)
        self.groups = 1
        self.bias = False
        self.conv2d_cuda = conv2d_cuda  # custom CUDA function

    def forward(self, x):
        # conv2d_cuda expects (x, out_channels)
        return self.conv2d_cuda(x, self.out_channels)


